    38	function pickPalette(subject) {
    39	  const s = String(subject || '');
    40	  if (/融资|路演|pitch|seed|投资|估值/i.test(s)) return 'pitch';
    41	  if (/新能源|光伏|风电|能源|碳|绿色|气候|机器人|产业研究/i.test(s)) return 'moss-amber';
    42	  if (/文化|历史|品牌|故事|杂志/i.test(s)) return 'ink-paper';
    43	  if (/夜|发布会|keynote/i.test(s)) return 'night-copper';
    44	  return 'moss-amber';
    45	}
